import { adminPermission } from '@/utils/globalSetting';
export default [
    {
        path: '/groupClass/showcase',
        name: 'GroupClassShowcase',
        component: () => import('@/views/Course/GroupClassShowcase'),
        meta: {
            requireAuth: [{ adminPermission: adminPermission.AddGroupClassShowcase }
                , { adminPermission: adminPermission.SelectGroupClassShowcase }]
        }
    },
    {
        path: '/groupClass/showcase/add',
        name: 'AddGroupClassShowcase',
        component: () => import('@/views/Course/AddGroupClassShowcase'),
        meta: { requireAuth: [{ adminPermission: adminPermission.AddGroupClassShowcase }] }
    },
    {
        path: '/groupClass/showcase/detail',
        name: 'GroupClassShowcaseDetail',
        component: () => import('@/views/Course/GroupClassShowcaseDetail'),
        meta: {
            requireAuth: [{ adminPermission: adminPermission.AddGroupClassShowcase }
                , { adminPermission: adminPermission.SelectGroupClassShowcase }
            ]
        }
    },
    {
        path: '/groupClass/showcase/edit',
        name: 'EditGroupClassShowcase',
        component: () => import('@/views/Course/EditGroupClassShowcase'),
        meta: {
            requireAuth: [{ adminPermission: adminPermission.AddGroupClassShowcase }]
        }
    },
];